START = datetime(2026, 11, 16, 10, 0, 0, tzinfo=UTC)


class Clock:
    """Hands out increasing UTC timestamps, one second apart, so a record's order is exact."""

    def __init__(self) -> None:
        self.seconds = 0

    def tick(self) -> str:
        """Return the next timestamp as the record writes it (`...Z`)."""
        self.seconds += 1
        return (START + timedelta(seconds=self.seconds)).strftime("%Y-%m-%dT%H:%M:%S.000Z")


class Session:
    """One transcript file: claude session jsonl (default) or a codex rollout."""

    def __init__(self, record: Record, dialect: str) -> None:
        self.record = record
        self.dialect = dialect
        self.lines: list[str] = []
        self.assistant_lines = 0
        self.patch_calls: set[str] = set()

    def emit(self, obj: dict[str, Any]) -> None:
        """Append one JSON line."""
        self.lines.append(json.dumps(obj))

    def raw(self, text: str) -> None:
        """Append a line as it is (to make a broken record)."""
        self.lines.append(text)

    def ask(self, text: str) -> None:
        """Record a user message."""
        ts = self.record.clock.tick()
        if self.dialect == "codex":
            payload = {"type": "message", "role": "user", "content": [{"type": "input_text", "text": text}]}
            self.emit({"timestamp": ts, "type": "response_item", "payload": payload})
        else:
            self.emit({"type": "user", "timestamp": ts, "message": {"role": "user", "content": text}})

    def say(self, text: str) -> None:
        """Record an assistant message."""
        ts = self.record.clock.tick()
        self.assistant_lines += 1
        if self.dialect == "codex":
            block = {"type": "output_text", "text": text}
            payload = {"type": "message", "role": "assistant", "content": [block]}
            self.emit({"timestamp": ts, "type": "response_item", "payload": payload})
        else:
            message = {"role": "assistant", "content": [{"type": "text", "text": text}]}
            self.emit({"type": "assistant", "timestamp": ts, "message": message})

    def call(self, tool: str, tool_input: dict[str, Any]) -> str:
        """Record a tool call and return its id."""
        ts = self.record.clock.tick()
        call_id = self.record.next_tool_id()
        self.assistant_lines += 1
        if self.dialect == "codex" and tool == "apply_patch":
            payload = {
                "type": "custom_tool_call",
                "status": "completed",
                "call_id": call_id,
                "name": "apply_patch",
                "input": tool_input["input"],
            }
            self.emit({"timestamp": ts, "type": "response_item", "payload": payload})
        elif self.dialect == "codex":
            arguments = (
                {"command": ["bash", "-lc", tool_input["command"]], "workdir": "/repo", "timeout_ms": 10000}
                if tool == "Bash"
                else tool_input
            )
            payload = {
                "type": "function_call",
                "name": "shell" if tool == "Bash" else tool,
                "arguments": json.dumps(arguments),
                "call_id": call_id,
            }
            self.emit({"timestamp": ts, "type": "response_item", "payload": payload})
        else:
            block = {"type": "tool_use", "id": call_id, "name": tool, "input": tool_input}
            self.emit(
                {"type": "assistant", "timestamp": ts, "message": {"role": "assistant", "content": [block]}}
            )
        return call_id

    def result(self, call_id: str, text: str, is_error: bool = False) -> None:
        """Record a tool result."""
        ts = self.record.clock.tick()
        if self.dialect == "codex" and call_id in self.patch_calls:
            payload = {"type": "custom_tool_call_output", "call_id": call_id, "output": text}
            self.emit({"timestamp": ts, "type": "response_item", "payload": payload})
        elif self.dialect == "codex":
            # What codex 0.163 hands the model for a shell call (`format_exec_output_for_model_freeform`).
            output = f"Exit code: {1 if is_error else 0}\nWall time: 0.3 seconds\nOutput:\n{text}"
            payload = {"type": "function_call_output", "call_id": call_id, "output": output}
            self.emit({"timestamp": ts, "type": "response_item", "payload": payload})
        else:
            block = {"tool_use_id": call_id, "type": "tool_result", "content": text, "is_error": is_error}
            self.emit({"type": "user", "timestamp": ts, "message": {"role": "user", "content": [block]}})

    def run(self, tool: str, tool_input: dict[str, Any], output: str, is_error: bool = False) -> str:
        """Record a tool call and its result."""
        call_id = self.call(tool, tool_input)
        self.result(call_id, output, is_error)
        return call_id

    def bash(self, command: str, output: str = "", is_error: bool = False) -> str:
        """Record a Bash call and its output."""
        return self.run("Bash", {"command": command}, output, is_error)

    def apply_patch(self, patch: str) -> str:
        """Record a codex `apply_patch` call (the file edit, authored text) and its output."""
        call_id = self.call("apply_patch", {"input": patch})
        self.patch_calls.add(call_id)
        self.result(call_id, "Success. Updated the following files:\nM src/tasklib/parse.py\n")
        return call_id

    def web_search(self, query: str, status: str = "completed", events: bool = False) -> None:
        """Record a codex hosted web search: a `web_search_call` item, and with `events` begin/end lines."""
        ts = self.record.clock.tick()
        self.assistant_lines += 1
        payload = {"type": "web_search_call", "status": status, "action": {"type": "search", "query": query}}
        self.emit({"timestamp": ts, "type": "response_item", "payload": payload})
        if events:
            self.emit(
                {
                    "timestamp": ts,
                    "type": "event_msg",
                    "payload": {"type": "web_search_begin", "call_id": "ws_1"},
                }
            )
            end = {"type": "web_search_end", "call_id": "ws_1", "query": query}
            self.emit({"timestamp": ts, "type": "event_msg", "payload": end})

    def codex_noise(self) -> None:
        """Record the lines a codex rollout holds besides the conversation: they must not become events."""
        ts = self.record.clock.tick()
        meta = {"id": "0199-codex", "cwd": "/repo", "originator": "codex_exec", "cli_version": "0.163.0"}
        self.emit({"timestamp": ts, "type": "session_meta", "payload": meta})
        self.emit({"timestamp": ts, "type": "turn_context", "payload": {"cwd": "/repo", "model": "gpt-5"}})
        self.emit({"timestamp": ts, "type": "event_msg", "payload": {"type": "task_started"}})
        reasoning = {"type": "reasoning", "summary": [], "encrypted_content": "gAAAA"}
        self.emit({"timestamp": ts, "type": "response_item", "payload": reasoning})


class Role:
    """One role of a record: its main transcript, sub-agent files, proxy and guard lines, and flaws."""

    def __init__(self, record: Record, role_id: str, kind: str, engine: str, parent: str) -> None:
        self.record = record
        self.role_id = role_id
        self.kind = kind
        self.engine = engine
        self.parent = parent
        self.main = Session(record, "codex" if engine == "codex" else "claude")
        self.files: dict[str, str] = {}
        self.sessions: dict[str, Session] = {}
        self.proxy: list[dict[str, Any]] = []
        self.guard: list[dict[str, Any]] = []
        # As `_seal_role.seal_flags`: Codex has no hook, so a sealed codex role has `guard` false.
        self.seal: dict[str, Any] = {
            "net": True,
            "guard": engine == "claude",
            "tools_off": True,
            "fs_readonly": True,
            "spec_sha256": SPEC_SHA,
        }
        self.final_text: str | None = "Done."
        self.registered_only = False
        self.write_end = True
        self.tamper = False
        self.no_transcript = False
        #: Files left out of the role dir (and so out of end.json), as when the harness lost one.
        self.omit: tuple[str, ...] = ()

    @property
    def main_path(self) -> str:
        """Where the main transcript lives under the role dir."""
        if self.engine == "codex":
            return "transcript/rollout-2026-11-16T10-00-00-" + self.role_id + ".jsonl"
        return "transcript/session.jsonl"

    @contextlib.contextmanager
    def agent(self, description: str, linked: bool = True, summary: str = "Done.") -> Iterator[Session]:
        """An in-session sub-agent (Agent tool): the call, its own transcript and meta, then the result.

        With `linked=False` the Agent call is recorded but no sub-agent transcript is, as when it was lost.
        """
        tool_use_id = self.main.call(
            "Agent", {"description": description, "subagent_type": "Explore", "prompt": "go"}
        )
        agent_id = "a" + hashlib.sha256(tool_use_id.encode()).hexdigest()[:16]
        sub = Session(self.record, "claude")
        yield sub
        sub.say(summary)
        if linked:
            base = f"transcript/session/subagents/agent-{agent_id}"
            self.sessions[base + ".jsonl"] = sub
            meta = {
                "agentType": "Explore",
                "description": description,
                "toolUseId": tool_use_id,
                "spawnDepth": 1,
            }
            self.files[base + ".meta.json"] = json.dumps(meta)
        self.main.result(tool_use_id, f"{summary}\nagentId: {agent_id} (for resuming)")

    def add_proxy(
        self, route: str, decision: str, target: str = "api.anthropic.com:443", status: int = 200
    ) -> None:
        """Add a proxy.jsonl line."""
        line = {"ts": self.record.clock.tick(), "method": "CONNECT", "target": target, "route": route}
        self.proxy.append({**line, "decision": decision, "rule": route, "status": status})

    def add_guard(self, tool: str, tool_input: dict[str, Any], decision: str, rule: str) -> None:
        """Add a guard.jsonl line."""
        line = {"ts": self.record.clock.tick(), "tool": tool, "input": tool_input}
        self.guard.append({**line, "decision": decision, "rule": rule})


class Record:
    """A record root under construction."""

    def __init__(self) -> None:
        self.clock = Clock()
        self.roles: list[Role] = []
        self.stray_roles: list[str] = []
        self.spec_sha = SPEC_SHA
        self.tool_counter = 0

    def next_tool_id(self) -> str:
        """Return a fresh tool call id."""
        self.tool_counter += 1
        return f"toolu_{self.tool_counter:04d}"

    def role(self, role_id: str, kind: str = "author", engine: str = "claude", parent: str = "") -> Role:
        """Add a role and return it, with the brief already in its transcript."""
        role = Role(self, role_id, kind, engine, parent)
        role.main.ask("Fix the bug described in the task. Do not look anywhere but the repo.")
        self.roles.append(role)
        return role

    def write(self, root: Path) -> None:
        """Write the record root: manifest first, then each role dir with end.json last."""
        root.mkdir(parents=True, exist_ok=True)
        entries = [
            {"role_id": r.role_id, "kind": r.kind, "registered_at": START.isoformat()} for r in self.roles
        ]
        (root / "manifest.json").write_text(json.dumps({"spec_sha256": self.spec_sha, "roles": entries}))
        for role in self.roles:
            if not role.registered_only:
                self.write_role(root / "roles" / role.role_id, role)
        for name in self.stray_roles:
            (root / "roles" / name).mkdir(parents=True)

    def write_role(self, role_dir: Path, role: Role) -> None:
        """Write one role dir; end.json is written last, from the files as they are then."""
        if role.final_text is not None and role.main.assistant_lines == 0:
            role.main.say(role.final_text)
        files = {} if role.no_transcript else {role.main_path: "\n".join(role.main.lines) + "\n"}
        files.update({path: "\n".join(s.lines) + "\n" for path, s in role.sessions.items()})
        files.update(role.files)
        files["proxy.jsonl"] = "".join(json.dumps(line) + "\n" for line in role.proxy)
        files["guard.jsonl"] = "".join(json.dumps(line) + "\n" for line in role.guard)
        files["role.json"] = json.dumps(
            {
                "role_id": role.role_id,
                "kind": role.kind,
                "engine": role.engine,
                "parent": role.parent,
                "action": "a0",
                "started_at": START.isoformat(),
                "seal": role.seal,
            }
        )
        for rel, text in files.items():
            if rel in role.omit:
                continue
            path = role_dir / rel
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text)
        if role.write_end:
            end = {"ended_at": START.isoformat(), "exit_code": 0, "files": hash_role_files(role_dir)}
            (role_dir / "end.json").write_text(json.dumps(end))
        if role.tamper:
            with (role_dir / role.main_path).open("a") as f:
                f.write(
                    json.dumps({"type": "user", "message": {"role": "user", "content": "added later"}}) + "\n"
                )

    def write_real(self, root: Path) -> None:
        """Write the record root with `_seal_record` itself, from a fake engine config dir per role.

        The corpus's own writer (`write`) can drift from what the launcher really writes; this one cannot.
        `register` runs before the role, `collect_claude`/`collect_codex` copy the transcripts out of a
        config dir laid out as Claude Code and Codex lay theirs out (with their extra line types), the proxy
        and guard logs are appended where `role_paths` says, and `finish` writes end.json last.
        """
        for role in self.roles:
            if role.final_text is not None and role.main.assistant_lines == 0:
                role.main.say(role.final_text)
            _seal_record.register(
                root,
                role.role_id,
                role.kind,
                engine=role.engine,
                parent=role.parent,
                action="a0",
                seal=role.seal,
            )
            paths = _seal_record.role_paths(root, role.role_id)
            with tempfile.TemporaryDirectory() as config:
                config_dir = Path(config)
                if role.engine == "codex":
                    main = config_dir / "sessions/2026/11/16" / Path(role.main_path).name
                    main.parent.mkdir(parents=True)
                    main.write_text("\n".join(role.main.lines) + "\n")
                    _seal_record.collect_codex(config_dir, paths.dir)
                else:
                    self.write_claude_config(config_dir, role)
                    _seal_record.collect_claude(config_dir, paths.dir)
            for log, lines in ((paths.proxy_log, role.proxy), (paths.guard_log, role.guard)):
                log.write_text("".join(json.dumps(line) + "\n" for line in lines))
            _seal_record.finish(root, role.role_id, 0)

    @staticmethod
    def write_claude_config(config_dir: Path, role: Role) -> None:
        """Lay a role's claude sessions out as `$CLAUDE_CONFIG_DIR` has them, lines in the real envelope."""
        session_id = "0b9d6e1c-5f0a-4a52-9a3e-6c1f2d7a8b90"
        project = config_dir / "projects" / "-home-flyte-repo"

        def lay(path: Path, session: Session, sidechain: bool, agent_id: str = "") -> None:
            envelope = {
                "isSidechain": sidechain,
                "userType": "external",
                "cwd": "/repo",
                "version": "2.1.326",
            }
            envelope |= {"sessionId": session_id, "entrypoint": "sdk-cli", "gitBranch": "HEAD"}
            if agent_id:
                envelope["agentId"] = agent_id
            lines = [
                json.dumps({"type": "queue-operation", "operation": "enqueue", "sessionId": session_id}),
                json.dumps({"type": "agent-setting", "agentSetting": "dev", "sessionId": session_id}),
            ]
            parent = None
            for number, raw in enumerate(session.lines):
                try:
                    obj = json.loads(raw)
                except json.JSONDecodeError:
                    lines.append(raw)
                    continue
                uuid = f"{agent_id or 'main'}-{number:04d}"
                lines.append(json.dumps({"parentUuid": parent, "uuid": uuid, **envelope, **obj}))
                parent = uuid
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text("\n".join(lines) + "\n")

        lay(project / f"{session_id}.jsonl", role.main, False)
        for rel, session in role.sessions.items():
            name = Path(rel).name
            lay(
                project / session_id / "subagents" / name,
                session,
                True,
                name.removeprefix("agent-").split(".")[0],
            )
        for rel, text in role.files.items():
            target = project / session_id / "subagents" / Path(rel).name
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(text)


def hash_role_files(role_dir: Path) -> dict[str, dict[str, Any]]:
    """Return end.json's `files`: sha256 and line count of every file under the role dir but end.json."""
    out: dict[str, dict[str, Any]] = {}
    for path in sorted(role_dir.rglob("*")):
        if path.is_file() and path.name != "end.json":
            data = path.read_bytes()
            lines = data.count(b"\n") + (1 if data and not data.endswith(b"\n") else 0)
            out[path.relative_to(role_dir).as_posix()] = {
                "sha256": hashlib.sha256(data).hexdigest(),
                "lines": lines,
            }
    return out


@dataclass(frozen=True)
class Case:
    """One corpus case: how to build the record, and the verdict (and reason) it truly deserves."""

    name: str
    build: Callable[[Record], None]
    expected: str
    reason: str = ""
    known_miss: bool = False
    note: str = ""
    real: bool = False


CASES: list[Case] = []


def case(
    name: str, expected: str, reason: str = "", known_miss: bool = False, note: str = "", real: bool = False
) -> Callable[[Callable[[Record], None]], Callable[[Record], None]]:
    """Register the decorated builder as a corpus case (`real`: see `Record.write_real`)."""

    def register(build: Callable[[Record], None]) -> Callable[[Record], None]:
        CASES.append(Case(name, build, expected, reason, known_miss, note, real))
        return build

    return register


def build_case(case_: Case, root: Path) -> None:
    """Write a case's record root."""
    record = Record()
    case_.build(record)
    record.write_real(root) if case_.real else record.write(root)


def audit_case(case_: Case, root: Path) -> _seal_audit.Verdict:
    """Write a case's record and audit it as the operator would (with the corpus gold)."""
    build_case(case_, root)
    return _seal_audit.audit(root, GOLD)


