def work(role: Role) -> None:
    """The ordinary work every run does: look around, run the tests."""
    role.main.bash("ls", "README.md\nsrc\ntests\n")
    role.main.run("Read", {"file_path": "/repo/src/tasklib/parse.py"}, PLAIN_FILE)
    role.main.bash("python -m pytest -q", "1 failed, 3 passed in 0.12s\n")


def routed(rec: Record, tool: str, tool_input: dict[str, Any], output: str, is_error: bool = False) -> None:
    """One author that makes one call that may reach upstream, and gets this result."""
    role = rec.role("author-1")
    work(role)
    role.main.run(tool, tool_input, output, is_error)
    role.main.say("I looked and then fixed it myself.")


def route_builder(
    tool: str, tool_input: dict[str, Any], output: str, is_error: bool = False
) -> Callable[[Record], None]:
    """A case builder for one call that may reach upstream, with the result it got."""
    return lambda rec: routed(rec, tool, tool_input, output, is_error)


