@case("clean-real-writer-with-subagent", "clean", real=True)
def real_clean(rec: Record) -> None:
    author = rec.role("author-1")
    work(author)
    with author.agent("explore the repo", summary="parse() lives in src/tasklib/parse.py.") as sub:
        sub.ask("Where is parse()?")
        sub.run("Read", {"file_path": "/repo/src/tasklib/parse.py"}, PLAIN_FILE)
    author.main.bash("git fetch origin", TUNNEL_403, is_error=True)
    author.add_proxy("model", "allow")
    author.add_proxy("index", "allow", target="/index/simple/pytest/")
    author.add_proxy("files", "allow", target="/files/pytest-8.3.0-py3-none-any.whl")
    author.add_proxy("web", "deny", target="github.com:443", status=403)
    author.add_guard("Bash", {"command": "git fetch origin"}, "deny", "git-fetch")
    engine = rec.role("subagent-1", kind="subagent", parent="author-1")
    engine.main.bash("python -m pytest -q", "1 failed, 3 passed in 0.12s\n")


